/* playback/queue.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /* ---------- upcoming track queue ---------- */

  function queueItem(album, index) {
    const track = album?.tracks?.[index];
    if (!track) return null;
    return {
      albumId: album.id,
      albumTitle: album.title,
      cover: album.cover || null,
      index,
      title: track.title,
      path: track.path,
      formats: track.formats,
      tracks: album.tracks.map((item) => ({
        title: item.title, path: item.path, formats: item.formats,
      })),
    };
  }

  function enqueue(album, index) {
    if (P.programLocked) return false;
    const item = P.queueItem(album, index);
    if (!item) return false;
    P.state.queue.push(item);
    P.renderQueue();
    P.saveState();
    P.notify("queue");
    P.schedulePreload();
    return true;
  }

  function removeFromQueue(index) {
    if (P.programLocked || !Number.isInteger(index) || index < 0 || index >= P.state.queue.length) return false;
    P.state.queue.splice(index, 1);
    P.renderQueue();
    P.saveState();
    P.notify("queue");
    P.schedulePreload();
    return true;
  }

  function clearQueue() {
    if (P.programLocked || !P.state.queue.length) return;
    P.state.queue = [];
    P.renderQueue();
    P.saveState();
    P.notify("queue");
    P.schedulePreload();
  }

  function getQueue() {
    return P.state.queue.map((item) => ({ ...item }));
  }

  function playQueued(index) {
    if (P.programLocked) return;
    const item = P.state.queue[index];
    if (!item) return;
    const commit = () => {
      P.state.queue.splice(index, 1);
      P.state.context = {
        albumId: item.albumId,
        title: item.albumTitle,
        cover: item.cover,
        tracks: item.tracks || [],
      };
      P.state.current = {
        albumId: item.albumId,
        index: item.index,
        title: item.title,
        path: item.path,
        formats: item.formats,
        cover: item.cover,
      };
      P.state.time = 0;
      P.showBar();
      P.renderMetadata();
      P.loadCurrent({ autoplay: true, startTime: 0, fadeIn: true });
      P.renderQueue();
      P.saveState();
      P.notify("queue");
      P.notify("track");
    };
    P.beginCrossfade(item, commit);
  }

  /* ---------- next-track preload ---------- */

  // Shuffle must choose the next index once and remember it: otherwise the
  // preloaded file and the file next() actually picks would be different.
  function pickShuffleIndex() {
    const tracks = P.state.context?.tracks;
    const length = tracks?.length || 0;
    if (!length) return null;
    if (P.shufflePick == null || P.shufflePick < 0 || P.shufflePick >= length
      || (P.state.current && P.shufflePick === P.state.current.index)) {
      if (length === 1) P.shufflePick = 0;
      else {
        do { P.shufflePick = Math.floor(Math.random() * length); }
        while (P.shufflePick === P.state.current?.index);
      }
    }
    return P.shufflePick;
  }

  function upcomingTrack() {
    if (P.state.queue.length) return P.state.queue[0];
    const tracks = P.state.context?.tracks;
    if (!P.state.current || !tracks?.length) return null;
    if (P.state.shuffle) {
      const index = P.pickShuffleIndex();
      return index == null ? null : tracks[index];
    }
    const nextIndex = P.state.current.index + 1;
    if (nextIndex < tracks.length) return tracks[nextIndex];
    // Manual "next" and repeat/auto-next wrap to the first track.
    if (P.state.repeat === "all" || P.state.autoNext) return tracks[0];
    return null;
  }

  function cancelPreload() {
    if (P.preloadTimer) { window.clearTimeout(P.preloadTimer); P.preloadTimer = 0; }
    P.preloadUrl = "";
    if (!P.preloadAudio) return;
    try { P.preloadAudio.pause(); } catch {}
    try { P.preloadAudio.removeAttribute("src"); P.preloadAudio.load(); } catch {}
  }

  function schedulePreload(delay = 300) {
    if (P.preloadTimer) window.clearTimeout(P.preloadTimer);
    if (!P.state.current || !P.preloadAudio) { P.cancelPreload(); return; }
    P.preloadTimer = window.setTimeout(P.updatePreload, delay);
  }

  function updatePreload() {
    P.preloadTimer = 0;
    const upcoming = P.upcomingTrack();
    if (!upcoming) { P.cancelPreload(); return; }
    const apply = () => {
      if (P.upcomingTrack() !== upcoming) return;
      const url = P.playableUrl(upcoming);
      if (!url || url === P.preloadUrl || url === P.playableUrl(P.state.current)) return;
      P.preloadUrl = url;
      try {
        P.preloadAudio.src = url;
        P.preloadAudio.load();
      } catch {
        P.preloadUrl = "";
      }
    };
    // Bake the upcoming track ahead of time: the actual switch then reuses the
    // blob instead of making the listener wait for an OfflineAudioContext pass.
    if (P.anyFxEnabled() && !P.isTrackRendered(upcoming)) {
      P.ensureRenderedTrack(upcoming).then(apply, apply);
      return;
    }
    apply();
  }
  Object.assign(P, { queueItem, enqueue, removeFromQueue, clearQueue, getQueue, playQueued, pickShuffleIndex, upcomingTrack, cancelPreload, schedulePreload, updatePreload });
}
